"""Recursive-descent parser for the SQL dialect described in SPEC.md.

``parse(sql)`` turns one ``SELECT`` statement into an :class:`ast.Select`.
It performs syntax checking only; names of tables and columns, function
names, and argument counts are the engine/evaluator's responsibility.
"""

from . import ast
from .errors import QueryError
from .lexer import lex

_COMPARISON_OPS = frozenset({"=", "!=", "<>", "<", "<=", ">", ">="})
_ADDITIVE_OPS = frozenset({"+", "-", "||"})
_MULTIPLICATIVE_OPS = frozenset({"*", "/"})
_NEGATABLE_PREDICATES = frozenset({"IN", "BETWEEN", "LIKE"})


class _Expr:
    """An expression node together with the source span it came from."""

    __slots__ = ("node", "start", "end")

    def __init__(self, node, start, end):
        self.node = node
        self.start = start
        self.end = end


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = lex(sql)
        self.pos = 0

    # -- token helpers -----------------------------------------------------

    def _peek(self, offset=0):
        index = self.pos + offset
        if index >= len(self.tokens):
            index = len(self.tokens) - 1
        return self.tokens[index]

    def _previous(self):
        return self.tokens[self.pos - 1]

    def _advance(self):
        token = self.tokens[self.pos]
        if token.kind != "EOF":
            self.pos += 1
        return token

    def _at_keyword(self, *words):
        token = self._peek()
        return token.kind == "KEYWORD" and token.value in words

    def _at_op(self, *ops):
        token = self._peek()
        return token.kind == "OP" and token.text in ops

    def _at_punct(self, *chars):
        token = self._peek()
        return token.kind == "PUNCT" and token.text in chars

    def _match_keyword(self, word):
        if self._at_keyword(word):
            return self._advance()
        return None

    def _match_punct(self, char):
        if self._at_punct(char):
            return self._advance()
        return None

    def _expect_keyword(self, word):
        if not self._at_keyword(word):
            self._fail("expected %s" % word)
        return self._advance()

    def _expect_punct(self, char):
        if not self._at_punct(char):
            self._fail("expected %r" % char)
        return self._advance()

    def _expect_name(self, description):
        token = self._peek()
        if token.kind != "NAME":
            self._fail("expected %s" % description)
        return self._advance()

    def _fail(self, message, token=None):
        token = self._peek() if token is None else token
        if token.kind == "EOF":
            found = "end of input"
        else:
            found = repr(token.text)
        raise QueryError(
            "syntax error at position %d: %s, found %s"
            % (token.start, message, found)
        )

    def _node(self, cls, start, end, *args, **kwargs):
        node = cls(*args, text=self.sql[start:end], **kwargs)
        return _Expr(node, start, end)

    # -- query -------------------------------------------------------------

    def parse_query(self):
        if self._peek().kind == "EOF":
            self._fail("expected SELECT")
        self._expect_keyword("SELECT")

        distinct = self._match_keyword("DISTINCT") is not None
        items = self._parse_select_items()

        self._expect_keyword("FROM")
        table_token = self._expect_name("a table name")
        table = table_token.value

        where = None
        if self._match_keyword("WHERE") is not None:
            where = self._parse_expr().node

        group_by = []
        if self._match_keyword("GROUP") is not None:
            self._expect_keyword("BY")
            group_by.append(self._parse_expr().node)
            while self._match_punct(",") is not None:
                group_by.append(self._parse_expr().node)

        having = None
        if self._match_keyword("HAVING") is not None:
            having = self._parse_expr().node

        order_by = []
        if self._match_keyword("ORDER") is not None:
            self._expect_keyword("BY")
            while True:
                order_by.append(self._parse_order_item())
                if self._match_punct(",") is None:
                    break

        limit = None
        offset = None
        if self._match_keyword("LIMIT") is not None:
            limit = self._parse_limit_value("LIMIT")
            if self._match_keyword("OFFSET") is not None:
                offset = self._parse_limit_value("OFFSET")

        # A semicolon is allowed only as the very last token.
        self._match_punct(";")

        if self._peek().kind != "EOF":
            token = self._peek()
            if (
                token.kind == "KEYWORD"
                and token.value == "OFFSET"
                and offset is None
            ):
                self._fail("OFFSET requires LIMIT", token)
            self._fail("unexpected token", token)

        return ast.Select(
            items=items,
            table=table,
            distinct=distinct,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
            text=self.sql,
        )

    def _parse_select_items(self):
        if self._at_op("*"):
            star_token = self._advance()
            if self._at_punct(","):
                self._fail("'*' must be the only select item")
            star = ast.Star(text=star_token.text)
            return [
                ast.SelectItem(star, text=self.sql[star_token.start:star_token.end])
            ]

        items = []
        while True:
            expr = self._parse_expr()
            alias = None
            end = expr.end
            if self._match_keyword("AS") is not None:
                alias_token = self._expect_name("an alias after AS")
                alias = alias_token.value
                end = alias_token.end
            elif self._peek().kind == "NAME":
                # A bare name directly after the expression is an alias.  A
                # number (or a keyword) never is.
                alias_token = self._advance()
                alias = alias_token.value
                end = alias_token.end
            items.append(
                ast.SelectItem(
                    expr.node, alias=alias, text=self.sql[expr.start:end]
                )
            )
            if self._match_punct(",") is None:
                break
            if self._at_op("*"):
                self._fail("'*' must be the only select item")

        return items

    def _parse_order_item(self):
        expr = self._parse_expr()
        descending = False
        end = expr.end
        if self._match_keyword("ASC") is not None:
            end = self._previous().end
        elif self._match_keyword("DESC") is not None:
            descending = True
            end = self._previous().end
        return ast.OrderItem(
            expr.node,
            descending=descending,
            text=self.sql[expr.start:end],
        )

    def _parse_limit_value(self, clause):
        token = self._peek()
        if token.kind != "NUMBER" or not isinstance(token.value, int):
            self._fail("%s requires a non-negative integer" % clause)
        if token.value < 0:
            self._fail("%s requires a non-negative integer" % clause)
        self._advance()
        return token.value

    # -- expressions -------------------------------------------------------

    def _parse_expr(self):
        return self._parse_or()

    def _parse_or(self):
        left = self._parse_and()
        while self._at_keyword("OR"):
            self._advance()
            right = self._parse_and()
            left = self._binary("OR", left, right)
        return left

    def _parse_and(self):
        left = self._parse_not()
        while self._at_keyword("AND"):
            self._advance()
            right = self._parse_not()
            left = self._binary("AND", left, right)
        return left

    def _parse_not(self):
        if self._at_keyword("NOT"):
            token = self._advance()
            operand = self._parse_not()
            return self._node(
                ast.UnaryOp, token.start, operand.end, "NOT", operand.node
            )
        return self._parse_comparison()

    def _parse_comparison(self):
        left = self._parse_additive()
        result = None

        token = self._peek()
        if token.kind == "OP" and token.text in _COMPARISON_OPS:
            op = self._advance().text
            right = self._parse_additive()
            result = self._node(
                ast.BinaryOp, left.start, right.end, op, left.node, right.node
            )
        elif self._at_keyword("IS"):
            self._advance()
            negated = self._match_keyword("NOT") is not None
            null_token = self._expect_keyword("NULL")
            result = self._node(
                ast.IsNull,
                left.start,
                null_token.end,
                left.node,
                negated=negated,
            )
        elif self._at_keyword("IN"):
            result = self._parse_in(left, False)
        elif self._at_keyword("BETWEEN"):
            result = self._parse_between(left, False)
        elif self._at_keyword("LIKE"):
            result = self._parse_like(left, False)
        elif self._negated_predicate_ahead():
            self._advance()  # NOT
            if self._at_keyword("IN"):
                result = self._parse_in(left, True)
            elif self._at_keyword("BETWEEN"):
                result = self._parse_between(left, True)
            else:
                result = self._parse_like(left, True)

        if result is not None:
            # Comparisons are non-associative: ``a = b = c`` is an error.
            if self._comparison_ahead():
                self._fail("comparison operators cannot be chained")
            return result

        return left

    def _negated_predicate_ahead(self):
        if not self._at_keyword("NOT"):
            return False
        token = self._peek(1)
        return token.kind == "KEYWORD" and token.value in _NEGATABLE_PREDICATES

    def _comparison_ahead(self):
        token = self._peek()
        if token.kind == "OP" and token.text in _COMPARISON_OPS:
            return True
        if token.kind == "KEYWORD":
            if token.value in ("IS", "IN", "BETWEEN", "LIKE"):
                return True
            if token.value == "NOT":
                token = self._peek(1)
                return (
                    token.kind == "KEYWORD"
                    and token.value in _NEGATABLE_PREDICATES
                )
        return False

    def _parse_in(self, left, negated):
        self._expect_keyword("IN")
        self._expect_punct("(")
        if self._at_punct(")"):
            self._fail("expected at least one expression in IN list")
        items = [self._parse_expr().node]
        while self._match_punct(",") is not None:
            items.append(self._parse_expr().node)
        close_token = self._expect_punct(")")
        return self._node(
            ast.InList,
            left.start,
            close_token.end,
            left.node,
            items,
            negated=negated,
        )

    def _parse_between(self, left, negated):
        self._expect_keyword("BETWEEN")
        # The bounds are additive expressions so BETWEEN's own AND is not
        # swallowed by the surrounding boolean parser.
        low = self._parse_additive()
        self._expect_keyword("AND")
        high = self._parse_additive()
        return self._node(
            ast.Between,
            left.start,
            high.end,
            left.node,
            low.node,
            high.node,
            negated=negated,
        )

    def _parse_like(self, left, negated):
        self._expect_keyword("LIKE")
        pattern = self._parse_additive()
        return self._node(
            ast.Like,
            left.start,
            pattern.end,
            left.node,
            pattern.node,
            negated=negated,
        )

    def _parse_additive(self):
        left = self._parse_multiplicative()
        while True:
            token = self._peek()
            if token.kind != "OP" or token.text not in _ADDITIVE_OPS:
                return left
            self._advance()
            right = self._parse_multiplicative()
            left = self._binary(token.text, left, right)

    def _parse_multiplicative(self):
        left = self._parse_unary()
        while True:
            token = self._peek()
            if token.kind != "OP" or token.text not in _MULTIPLICATIVE_OPS:
                return left
            self._advance()
            right = self._parse_unary()
            left = self._binary(token.text, left, right)

    def _binary(self, op, left, right):
        return self._node(
            ast.BinaryOp, left.start, right.end, op, left.node, right.node
        )

    def _parse_unary(self):
        if self._at_op("-"):
            token = self._advance()
            operand = self._parse_unary()
            return self._node(
                ast.UnaryOp, token.start, operand.end, "-", operand.node
            )
        return self._parse_primary()

    def _parse_primary(self):
        token = self._peek()

        if token.kind == "NUMBER":
            self._advance()
            return self._node(ast.Literal, token.start, token.end, token.value)

        if token.kind == "STRING":
            self._advance()
            return self._node(ast.Literal, token.start, token.end, token.value)

        if token.kind == "NAME":
            self._advance()
            if self._at_punct("("):
                return self._parse_function_call(token)
            return self._node(
                ast.ColumnRef, token.start, token.end, token.value
            )

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self._advance()
                return self._node(ast.Literal, token.start, token.end, None)
            if token.value == "TRUE":
                self._advance()
                return self._node(ast.Literal, token.start, token.end, True)
            if token.value == "FALSE":
                self._advance()
                return self._node(ast.Literal, token.start, token.end, False)
            self._fail("expected an expression (keyword may not be used here)")

        if token.kind == "PUNCT" and token.text == "(":
            open_token = self._advance()
            inner = self._parse_expr()
            close_token = self._expect_punct(")")
            # Parentheses are part of the expression's source text.
            inner.node.text = self.sql[open_token.start:close_token.end]
            inner.start = open_token.start
            inner.end = close_token.end
            return inner

        if token.kind == "OP" and token.text == "*":
            self._fail(
                "'*' is only allowed as a select item or as a function argument"
            )

        self._fail("expected an expression")

    def _parse_function_call(self, name_token):
        self._expect_punct("(")
        args = []
        if self._at_op("*"):
            star_token = self._advance()
            args.append(ast.Star(text=star_token.text))
            if not self._at_punct(")"):
                self._fail("'*' must be the only function argument")
        elif not self._at_punct(")"):
            args.append(self._parse_expr().node)
            while self._match_punct(",") is not None:
                args.append(self._parse_expr().node)
        close_token = self._expect_punct(")")
        return self._node(
            ast.FuncCall,
            name_token.start,
            close_token.end,
            name_token.value,
            args,
        )


def parse(sql):
    """Parse one ``SELECT`` statement and return an :class:`ast.Select`.

    Raises :class:`~minisql.errors.QueryError` on any syntax error.
    """
    if not isinstance(sql, str):
        raise QueryError("SQL query must be a string")
    return _Parser(sql).parse_query()

