from minisql.parser import parse
from minisql import ast
from minisql.errors import QueryError


def dump(node, indent=0):
    pad = "  " * indent
    if isinstance(node, ast.Node):
        print(pad + type(node).__name__ + " text=" + repr(node.text))
        for k, v in node.__dict__.items():
            if k == "text":
                continue
            print(pad + "  " + k + ":")
            if isinstance(v, ast.Node):
                dump(v, indent + 2)
            elif isinstance(v, list):
                if not v:
                    print("  " * (indent + 3) + "[]")
                for item in v:
                    if isinstance(item, ast.Node):
                        dump(item, indent + 3)
                    else:
                        print("  " * (indent + 3) + repr(item))
            else:
                print("  " * (indent + 2) + repr(v))


queries = [
    "SELECT DISTINCT name, price * 2 AS double FROM products WHERE price > 10 AND category NOT IN ('a', NULL) ORDER BY 2 DESC LIMIT 5 OFFSET 1;",
    "SELECT COUNT(*) FROM t",
    'SELECT "unit price" FROM t',
    "SELECT 'it''s' FROM t",
    "SELECT -1 + 2 * 3 FROM t",
    "SELECT a FROM t WHERE NOT (b = 1 OR c IS NOT NULL)",
    "SELECT a, COUNT(*) FROM t GROUP BY a HAVING COUNT(*) > 1",
]
for q in queries:
    print("=" * 70)
    print(q)
    stmt = parse(q)
    dump(stmt)

print("=" * 70)
bad = [
    "SELECT",
    "SELECT * x FROM t",
    "SELECT a FROM t extra",
    "SELECT a FROM t WHERE",
    "SELECT a = b = c FROM t",
    "SELECT a BETWEEN 1 OR 2 FROM t",
]
